133	/**
134	 * Return the most recent backup/restore job for a server so the UI can render a
135	 * live progress bar. Ownership-checked. Returns null if the server has never had
136	 * a backup/restore job. The client decides when to show the bar (in-flight) vs.
137	 * the completion/failure note.
138	 */
139	export async function getBackupJob(serverId: string): Promise<BackupJobStatus | null> {
140	  const { server } = await ownedServer(serverId);
141	  const job = await db.job.findFirst({
142	    where: { serverId: server.id, type: { in: ["BACKUP_CREATE", "BACKUP_RESTORE"] } },
143	    orderBy: { createdAt: "desc" },
144	    select: { id: true, type: true, status: true, progress: true, step: true, error: true, createdAt: true },
145	  });
146	  if (!job) return null;
147	  return {
148	    id: job.id,
149	    type: job.type as BackupJobStatus["type"],
150	    status: job.status as BackupJobStatus["status"],
151	    progress: job.progress,
152	    step: job.step,
153	    error: job.error,
154	    createdAt: job.createdAt.toISOString(),
155	  };
