343	/**
344	 * Rename a paid Minecraft server's `<subdomain>.play.nxeon.cloud`. Mirrors
345	 * lib/actions-free-minecraft.ts's changeFreeMinecraftSubdomain: format/reserved
346	 * check, then let the DB's unique constraint (Server.subdomain) catch the
347	 * same-table race rather than a separate findFirst-then-update (TOCTOU).
348	 */
349	export async function changeGameSubdomain(prev: unknown, formData: FormData): Promise<{ error?: string }> {
350	  const serverId = String(formData.get("serverId") ?? "");
351	  const { user, server } = await ownedServer(serverId);
352	
353	  const rl = checkRateLimit(`game:subdomain:${user.id}`, { max: 5, windowMs: 300_000 });
354	  if (!rl.ok) return { error: `Too many attempts — try again in ${Math.ceil(rl.retryAfterSec / 60)}m.` };
355	
356	  const sub = String(formData.get("subdomain") ?? "").trim().toLowerCase();
357	  const formatError = validateSubdomainFormat(sub);
358	  if (formatError) return { error: formatError };
359	  if (sub === server.subdomain) return {};
360	
361	  if (!(await isSubdomainAvailable(sub, { excludeServerId: serverId }))) {
362	    return { error: "That name is taken — try another." };
363	  }
364	
365	  try {
366	    await db.server.update({ where: { id: serverId }, data: { subdomain: sub } });
367	  } catch (e: any) {
368	    if (e?.code === "P2002") return { error: "That name is taken — try another." };
369	    throw e;
370	  }
371	
372	  await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId } });
373	  await db.auditLog.create({
374	    data: { userId: user.id, action: "server.game_subdomain_change", detail: `${serverId} -> ${sub}` },
375	  });
376	  revalidatePath(`/dashboard/servers/${serverId}`);
377	  return {};
378	}
