11	 * incident (planned maintenance, a customer-visible degradation the auto-monitor
12	 * can't infer) and resolve it when it's over.
13	 *
14	 * "use server" means every export here is a public HTTP endpoint, so each one
15	 * re-checks `requireArea("fleet")` INSIDE the function — the admin page gate is
16	 * not enough on its own.
17	 *
18	 * Auto-opened incidents (auto=true) are owned by the sampleHealth() state
19	 * machine; these actions only touch operator-posted ones (auto=false) so a
20	 * manual resolve can never fight the auto-resolver over the same row.
21	 */
22	
23	const SEVERITIES: IncidentSeverity[] = ["degraded", "down", "maintenance"];
24	
25	type Result = { ok?: boolean; id?: string; error?: string };
