27	export async function postIncident(input: {
28	  title: string;
29	  body?: string;
30	  severity: string;
31	  component?: string | null;
32	}): Promise<Result> {
33	  const admin = await requireArea("fleet");
34	
35	  const title = (input.title ?? "").trim();
36	  if (!title) return { error: "A title is required." };
37	  if (title.length > 140) return { error: "Title is too long (max 140 characters)." };
38	
39	  const severity = SEVERITIES.includes(input.severity as IncidentSeverity)
40	    ? (input.severity as IncidentSeverity)
41	    : "degraded";
42	
43	  // Empty string ⇒ platform-wide; otherwise it must be one of the known components.
44	  const rawComponent = (input.component ?? "").trim();
45	  let component: string | null = null;
46	  if (rawComponent) {
47	    if (!(HEALTH_COMPONENTS as readonly string[]).includes(rawComponent)) {
48	      return { error: "Unknown component." };
49	    }
50	    component = rawComponent;
51	  }
52	
53	  const body = (input.body ?? "").trim().slice(0, 2000);
54	
55	  const incident = await db.statusIncident.create({
56	    data: { title, body, severity, component, auto: false },
57	  });
58	
59	  await db.auditLog.create({
60	    data: { userId: admin.id, action: "status.incident.post", detail: `${severity} — ${title}` },
61	  });
62	  await alertIncidentOpened(incident);
63	
64	  revalidatePath("/admin/monitoring");
65	  revalidatePath("/status");
66	  return { ok: true, id: incident.id };
