3	// Server actions for connecting/disconnecting a customer's own Anthropic API
4	// key (BYOK). Only async functions are exported (Next.js "use server" rule).
5	// The stored key is AES-256-GCM encrypted at rest and NEVER returned to the
6	// client — callers can only learn whether a key is connected, not its value.
7	
8	import { revalidatePath } from "next/cache";
9	import { db } from "./db";
10	import { requireUser } from "./auth";
11	import { encryptSecret } from "./crypto-box";
12	import { platformKeyConfigured } from "./anthropic";
13	
14	// Anthropic keys look like `sk-ant-api03-...` — a stable, recognizable prefix
15	// followed by an opaque token. We validate shape only (never call the API here).
16	const ANTHROPIC_KEY_RE = /^sk-ant-[A-Za-z0-9_-]{20,}$/;
17	
18	export async function connectAnthropicKey(key: string): Promise<{ error?: string; ok?: boolean }> {
19	  const user = await requireUser();
20	
21	  const clean = (key ?? "").trim();
22	  if (!clean) {
23	    return { error: "Please paste your Anthropic API key." };
24	  }
25	  if (!ANTHROPIC_KEY_RE.test(clean)) {
26	    return { error: 'That doesn’t look like an Anthropic API key — it should start with "sk-ant-".' };
27	  }
28	
29	  await db.user.update({
30	    where: { id: user.id },
31	    data: { anthropicKeyEnc: encryptSecret(clean) },
32	  });
33	
34	  await db.auditLog
35	    .create({ data: { userId: user.id, action: "user.anthropic_key_connect", detail: "connected" } })
36	    .catch(() => {});
37	
38	  // The key is managed in Settings; the planner reads it to decide if it can run.
39	  revalidatePath("/dashboard/settings");
40	  revalidatePath("/dashboard/build");
41	  return { ok: true };
42	}
43	
44	export async function disconnectAnthropicKey(): Promise<{ ok: boolean }> {
45	  const user = await requireUser();
46	
47	  await db.user.update({
48	    where: { id: user.id },
49	    data: { anthropicKeyEnc: null },
50	  });
51	
52	  await db.auditLog
53	    .create({ data: { userId: user.id, action: "user.anthropic_key_disconnect", detail: "disconnected" } })
54	    .catch(() => {});
55	
56	  // The key is managed in Settings; the planner reads it to decide if it can run.
57	  revalidatePath("/dashboard/settings");
58	  revalidatePath("/dashboard/build");
59	  return { ok: true };
60	}
