62	/** Whether the current user has a stored key. Returns a boolean only — never the key. */
63	export async function hasAnthropicKey(): Promise<boolean> {
64	  const user = await requireUser();
65	  const u = await db.user.findUnique({
66	    where: { id: user.id },
67	    select: { anthropicKeyEnc: true },
68	  });
