505	/**
506	 * Grace added to a first-month-free hold's lifetime beyond the Checkout session's
507	 * payable window, so a payment landing at the very last instant still finds a live
508	 * hold to confirm. The `checkout.session.expired` webhook and the worker sweep only
509	 * reap holds past this, i.e. well after the session can no longer be paid.
510	 */
511	const RESERVATION_GRACE_MS = 10 * 60 * 1000;
512	
513	export async function payAndDeploy(
514	  prev: any,
515	  formData: FormData,
516	): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
517	  const user = await requireUser();
518	  // Spend path: never move a customer's money while an admin is impersonating them.
519	  // Caught (not left to throw uncaught) so an impersonating admin sees this exact
520	  // message inline — the bare throw used to crash the whole page with a generic
521	  // "Something went wrong" screen instead, a real bug hit every time an admin
522	  // testing the wizard while impersonating tried to pay.
523	  try {
524	    await assertNotImpersonating();
525	  } catch (e) {
526	    return { error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
527	  }
528	  // Same verification gate every purchase path applies. This is the CARD path, so it is the
529	  // one where an unreachable address is most expensive: without it we would take
530	  // a real payment for a machine whose credentials have nowhere to go.
531	  const unverified = await emailVerificationError(user);
532	  if (unverified) return { error: unverified };
533	  // Per-user server cap — the same one `orderGameServer` enforces for game tiers.
534	  const limitErr = await serverLimitError(user.id);
535	  if (limitErr) return { error: limitErr };
536	  const intent = intentFromFormData(formData);
537	  // Tag the order if the customer arrived via a partner deep link (?ref=kodely on
538	  // /dashboard/deploy, captured into a cookie by PartnerSourceCapture). Undefined
539	  // for a direct order, so it drops out of the Stripe-metadata JSON round-trip
540	  // like extraDiskGB/backupTier above.
541	  intent.partnerSource = partnerSourceFromCookie(await cookies());
542	
543	  let quote;
544	  try {
545	    quote = await orderQuote(intent);
546	  } catch (e) {
547	    if (e instanceof OrderError) return { error: e.message };
548	    throw e;
549	  }
550	
551	  // Managed first-month-free eligibility. If this account/IP has ALREADY redeemed
552	  // the promo (or it's switched off), re-quote at FULL price so the wallet split,
553	  // the card leg and the stamped total are all full — the free month is a
554	  // once-per-person offer. The wallet path is self-correcting regardless (its
555	  // atomic claim inside placeOrder charges full on a lost claim), but the CARD
556	  // leg settles up front, so it MUST be priced full here or a repeat customer
557	  // gets a second discounted checkout. This mirrors the coupon guard below.
558	  // `|| null` matters: hashIp returns "" when the IP is unavailable, and an empty
559	  // string is a REAL value to the (promoId, ipHash) unique — it would collide
560	  // across every IP-less redemption and wrongly block them. NULLs are distinct.
561	  const promoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
562	  if (quote.promoCreditCents > 0 && !(await firstMonthFreeEligible(user.id, promoIpHash))) {
563	    quote = await orderQuote(intent, { suppressPromo: true });
564	  }
565	  const promoCampaign = promoCampaignFromCookie(await cookies());
566	
567	  const isAdmin = user.role === "ADMIN";
568	  const freePath = !!intent.free && isAdmin;
569	
570	  // Wallet-aware split. The customer's Review screen computes the exact same split
571	  // (lib/wallet-split.ts) from the same inputs, so what they see === what we charge.
572	  // `useWallet` defaults ON (only "0" turns it off) so existing forms keep applying
573	  // the balance. Free admin grants skip the split entirely (no money moves).
574	  const useWallet = formData.get("useWallet") !== "0";
575	  // VAT/GST for this customer (Finding 1), resolved from their billing country. The
576	  // rate is constant for the request; the tax cents track whatever net the quote
577	  // settles on after any promo/coupon re-quote below. The wallet split and the card
578	  // leg are computed from the TAX-INCLUSIVE total so the card is charged the same
579	  // total the customer is shown, and the stamped `OrderPrice` carries the tax so the
580	  // confirm route settles it without re-deriving. A free admin grant is never taxed.
581	  const taxCtx = freePath ? { ratePercent: 0, country: "", reverseCharged: false } : await taxContextForUser(user);
582	  const taxOn = (netCents: number) => Math.round((netCents * taxCtx.ratePercent) / 100);
583	  const dueWithTax = (netCents: number) => netCents + taxOn(netCents);
584	  // `let`: a first-month-free hold lost to a concurrent checkout forces a full-price
585	  // re-quote below, which changes the split. Free admin grants skip it entirely.
586	  let { walletApplied, cardCents } = freePath
587	    ? { walletApplied: 0, cardCents: 0 }
588	    : walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet });
589	
590	  // Card portion is $0 (free admin grant, or the wallet fully covers the charge) →
591	  // provision straight away. placeOrder debits the FULL chargeCents from the wallet
592	  // (or nothing, for a free grant); the balance check inside it holds because a
593	  // $0 card portion means balance >= chargeCents.
594	  if (freePath || cardCents <= 0) {
595	    let serverId: string;
596	    try {
597	      // Reuse the request-scoped IP hash computed above so placeOrder can enforce
598	      // both the coupon's once-per-person guard and the first-month-free 1/IP cap.
599	      serverId = await placeOrder(user, intent, null, { ipHash: promoIpHash, campaign: promoCampaign });
600	    } catch (e) {
601	      if (e instanceof OrderError) return { error: e.message };
602	      throw e;
603	    }
604	    // A wallet-only order is still a real payment (money left the balance) — stamp
605	    // the same `?purchase=1` marker the card/Stripe path gets via reportPurchase, so
606	    // ProvisioningOverlay's "just paid" signal covers this path too. Skip it for a
607	    // free admin grant (freePath): no money moved, nothing to celebrate.
608	    redirect(`/dashboard/servers/${serverId}${freePath ? "" : "?purchase=1"}`);
609	  }
