753	async function ownedServer(serverId: string) {
754	  const user = await requireUser();
755	  const server = await db.server.findUnique({ where: { id: serverId } });
756	  if (!server) throw new Error("Not found");
757	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
758	  return { user, server };
