958	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
959	  // Spend path: block wallet debits while an admin is impersonating.
960	  await assertNotImpersonating();
961	  const { user, server } = await ownedServer(serverId);
962	  if (server.isFree || !server.expiresAt) return;
963	  // A MANUAL renewal is a fresh purchase decision, so it is gated. Note this
964	  // cannot strand an existing customer: every account that owns a server today
965	  // predates verification and is grandfathered, and the automatic renewal in
966	  // worker/billing.ts does not pass through here at all — nobody's server lapses
967	  // because of this check.
968	  const unverified = await emailVerificationError(user);
969	  if (unverified) return { error: unverified };
970	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
971	  if (!plan) return;
972	  // A game server carries BOTH a base `planId` and a `gamePlanId`, and it is sold
973	  // at the game plan's FLAT price. Reading only `plan.priceCents` here charged a
974	  // game-server owner the base VPS term price instead — `minecraft-mm8w85` sold at
975	  // $4.99 on a Starter base plan would have been billed $8.99, an 80% overcharge.
976	  const gamePlan = server.gamePlanId
977	    ? await db.gamePlan.findUnique({
978	        where: { id: server.gamePlanId },
979	        select: { name: true, priceCents: true, termMonths: true },
980	      })
981	    : null;
982	  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
983	  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
984	  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
985	    where: { serverId }, select: { id: true },
986	  }));
987	  // The SERVER OWNER (not necessarily the acting user) determines the VAT/GST rate
988	  // and the spend cap — resolved up front so `renewalQuote` prices tax-inclusive.
989	  const owner = await db.user.findUnique({ where: { id: server.userId } });
990	  if (!owner) return;
991	  const renewTaxCtx = await taxContextForUser(owner);
992	  // Priced through `renewalCharge` — the SAME function the automatic renewal sweep
993	  // in worker/billing.ts and the saved-card path use. Not a second copy of the
994	  // arithmetic: see lib/renewal-quote.ts for both incidents that produced this
995	  // rule, the second of which was a fresh duplicate written hours after the first.
996	  const quote = renewalQuote(
997	    {
998	      termMonths: server.termMonths,
999	      extraDiskGB: server.extraDiskGB,
1000	      plan: { name: plan.name, priceCents: plan.priceCents },
1001	      gamePlan,
1002	      dedicatedIp: hasDedicatedIp ? {} : null,
1003	      backupTier: server.backupTier,
1004	    },
1005	    {
1006	      ipMonthlyCents: hasDedicatedIp ? await dedicatedIpMonthlyCents() : 0,
1007	      extraDiskPerGbCents: await extraDiskPerGbCents(),
1008	      backupPlusCents: await backupPlusMonthlyCents(),
1009	      annualDiscountPct: await annualDiscountPct(),
1010	      // VAT/GST for the owner's country (Finding 1). `renewCents` below is
1011	      // tax-inclusive, so what the customer is shown === what the wallet is debited.
1012	      taxRatePercent: renewTaxCtx.ratePercent,
1013	    },
1014	  );
1015	  const renewCents = quote.totalCents;
1016	  const term = { months: quote.months };
1017	  const extraDiskMonthly = await extraDiskMonthlyCents(server.extraDiskGB);
1018	  const extraDiskCents = gamePlan ? 0 : extraDiskMonthly * quote.months;
1019	  if (owner.balanceCents < renewCents) {
1020	    return { error: "Insufficient balance — top up your wallet first." };
1021	  }
1022	  // Hard monthly spend cap (Finding 3): refuse a manual wallet renewal that would
1023	  // push the owner past their cap. No-op unless they enabled one.
1024	  try {
1025	    await assertSpendCap(owner, renewCents);
1026	  } catch (e) {
1027	    if (e instanceof SpendCapError) return { error: e.message };
1028	    throw e;
1029	  }
1030	
1031	  // `E` is the expiry we read OUTSIDE the transaction. We advance it with a
1032	  // compare-and-swap on that exact value so two concurrent "Renew now" clicks
1033	  // can't both read E, both debit, and both write E+term (double-charge, one
1034	  // term granted). Only the CAS that matches E wins; the loser is a no-op.
1035	  const E = server.expiresAt;
1036	  const base = new Date(Math.max(E.getTime(), Date.now()));
1037	  const newExpiry = addMonths(base, term.months);
1038	
1039	  // `renewCents` above is `vpsTermPriceCents(...)` — the REGULAR price, with no
1040	  // seasonal promo applied. That is exactly what lib/promotions.ts promises: the
1041	  // strikethrough on the marketing page is the real renewal price. So the months
1042	  // being added here are sold at 0% off, and the term's stored rate has to say so.
1043	  //
1044	  // BLENDED, not overwritten. A customer can renew early, stacking a full-price
1045	  // term on top of months still running at an intro discount. Overwriting would
1046	  // silently reprice those earlier months to full list — and that is the profitable
1047	  // direction: buy 36 months at 45% off, renew once at full price, and every one of
1048	  // the original discounted months would suddenly credit at the full rate on a
1049	  // downgrade. Blending keeps the cash value of the window invariant.
1050	  const renewedPercent = prorateBlendPercent({
1051	    currentPercent: resolveTermPromoPercent(server.termPromoPercent),
1052	    currentMonths: remainingMonths(E, Date.now()),
1053	    addedPercent: 0,
1054	    addedMonths: term.months,
1055	  });
1056	  try {
1057	    await db.$transaction(async (tx) => {
1058	      // Compare-and-swap the expiry first; if it no longer equals E another
1059	      // renewal already advanced it — bail without charging (tx rolls back).
1060	      const adv = await tx.server.updateMany({
1061	        where: { id: serverId, expiresAt: E },
1062	        data: {
1063	          expiresAt: newExpiry,
1064	          termPromoPercent: renewedPercent,
1065	          suspendedNote: null,
1066	          suspendReason: null,
1067	        },
1068	      });
1069	      if (adv.count === 0) throw new AlreadyRenewedError();
1070	      // Atomic guarded debit: a concurrent spend can't drive the wallet negative.
1071	      await debitWallet(tx, server.userId, renewCents);
1072	      await tx.walletTransaction.create({
1073	        data: {
1074	          userId: server.userId,
1075	          amountCents: -renewCents,
1076	          description: `Renewal: ${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
1077	        },
1078	      });
1079	      // PAID invoice inside the same CAS-guarded tx: a losing concurrent "Renew
1080	      // now" throws AlreadyRenewedError and rolls back, so no duplicate invoice.
1081	      await tx.invoice.create({
1082	        data: invoiceCreateData({
1083	          userId: server.userId,
1084	          description: `Renewal: ${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
1085	          status: "PAID",
1086	          // Tax recorded separately; the line items below sum to the NET (quote.netCents).
1087	          taxCents: quote.taxCents,
1088	          taxRatePercent: quote.taxRatePercent,
1089	          taxCountry: renewTaxCtx.country,
1090	          period: { start: E, end: newExpiry },
1091	          lineItems: [
1092	            {
1093	              description: `${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
1094	              qty: 1,
1095	              unitCents: quote.netCents - extraDiskCents,
1096	              amountCents: quote.netCents - extraDiskCents,
1097	            },
1098	            ...(extraDiskCents > 0
1099	              ? [
1100	                  {
1101	                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthly / 100).toFixed(2)}/mo)`,
1102	                    qty: 1,
1103	                    unitCents: extraDiskCents,
1104	                    amountCents: extraDiskCents,
1105	                  },
1106	                ]
1107	              : []),
1108	          ],
1109	        }),
1110	      });
1111	    });
1112	  } catch (e) {
1113	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
1114	    if (e instanceof AlreadyRenewedError) return { error: "This server was just renewed — refresh to see the new expiry." };
1115	    throw e;
1116	  }
1117	  await audit(user.id, "server.renew_now", serverId);
1118	  // Soft monthly-budget alert (Finding 3), best-effort.
1119	  await maybeAlertBudget(server.userId);
1120	  // KOL/Agency partner commission on this renewal charge (idempotent; best-effort).
1121	  await accrueRecentCommissionsForCustomer(server.userId);
1122	
1123	  // An UNPAID-suspended server springs back to life once paid — but only that
1124	  // kind. This used to fire for ANY suspended server, so a customer suspended for
1125	  // outbound abuse could click "Renew now", pay, and put themselves straight back
1126	  // on the network, undoing an abuse or admin action with a card. Legacy rows with
1127	  // a null `suspendReason` are not auto-lifted; an admin can clear those by hand.
1128	  if (server.status === "SUSPENDED" && server.suspendReason === "UNPAID") {
1129	    const pending = await db.job.count({
1130	      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
1131	    });
