30	async function ownedServer(
31	  serverId: string,
32	  userId: string,
33	  isAdmin: boolean
34	): Promise<SftpServer | null> {
35	  const server = await db.server.findUnique({
36	    where: { id: serverId },
37	    select: {
38	      id: true,
39	      userId: true,
40	      rootPassword: true,
41	      // The encrypted-at-rest password is the authoritative one for any server
42	      // provisioned after credential encryption shipped; the plaintext column is
43	      // null for those. serverRootPassword() prefers Enc and falls back to
44	      // plaintext, so BOTH must be selected — omitting Enc made every
45	      // encrypted-password server fail with "Server has no root password set."
46	      rootPasswordEnc: true,
47	      sshPort: true,
48	      dedicatedIp: { select: { address: true } },
49	    },
50	  });
51	  if (!server) return null;
52	  if (server.userId !== userId && !isAdmin) return null;
