56	export async function GET(
57	  req: NextRequest,
58	  { params }: { params: Promise<{ serverId: string }> }
59	) {
60	  const { serverId } = await params;
61	
62	  const user = await currentUser();
63	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
64	
65	  const rl = checkRateLimit(`files:download:${user.id}`, { max: 60, windowMs: 60_000 });
66	  if (!rl.ok) {
67	    return NextResponse.json(
68	      { error: "too many downloads — slow down", retryAfterSec: rl.retryAfterSec },
69	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
70	    );
71	  }
72	
73	  const server = await ownedServer(serverId, user.id, user.role === "ADMIN");
74	  if (!server) return NextResponse.json({ error: "not found" }, { status: 404 });
75	
76	  let path: string;
77	  try {
78	    path = normalizePath(req.nextUrl.searchParams.get("path") ?? "");
79	  } catch (err) {
80	    return NextResponse.json(
81	      { error: err instanceof Error ? err.message : "invalid path" },
82	      { status: 400 }
83	    );
84	  }
85	  if (path === "/") return NextResponse.json({ error: "not a file" }, { status: 400 });
86	
87	  let data: Buffer;
88	  try {
89	    data = await readFileBuffer(server, path);
90	  } catch (err) {
91	    const msg = err instanceof Error ? err.message : "read failed";
92	    const status = /No such|Not a file/i.test(msg) ? 404 : 502;
93	    return NextResponse.json({ error: msg }, { status });
94	  }
