96	  const filename = path.split("/").pop() || "download";
97	  // Always force a download to avoid the browser rendering server content inline.
98	  return new NextResponse(data as unknown as BodyInit, {
99	    status: 200,
100	    headers: {
101	      "Content-Type": "application/octet-stream",
102	      "Content-Length": String(data.length),
103	      "Content-Disposition": `attachment; filename="${filename.replace(/["\\]/g, "_")}"`,
