440	  // <ProvisioningOverlay/> (lib/provisioning-step.ts) — written between the real,
441	  // observable checkpoints below (Proxmox clone/config/start, guest-agent boot,
442	  // SSH reachability, and the game's own port opening). Never allowed to fail
443	  // the provision — it's purely a display aid, same discipline as worker/hosting.ts's
444	  // equivalent `step()`.
445	  const step = (label: string) =>
446	    db.server.update({ where: { id: server.id }, data: { provisioningStep: label } }).catch(() => undefined);
447	
448	  if (SANDBOX) {
449	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
450	    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
451	    const vmid = server.vmid ?? (990000 + (await db.server.count()));
452	    const password = generatePassword();
453	    const ip = sandboxIp(vmid);
454	    await db.server.update({
455	      where: { id: server.id },
456	      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
457	    });
458	    await notify(
459	      server.userId,
460	      `Server ${server.hostname} is ready`,
461	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
462	      `/dashboard/servers/${server.id}`
463	    );
464	    // Post-purchase review request (once per server, skipped if no profiles set).
465	    await sendReviewRequestForServer(server.id);
466	    return;
467	  }
468	
469	  const { conn, row: nodeRow } = await nodeFor(server);
470	  const storage = server.plan.storageTier === "hdd"
471	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
472	    : nodeRow?.storageNvme ?? "vmdata";
473	
474	  // Pick a vmid that does NOT still own a previous tenant's backup archives.
475	  // `/cluster/nextid` hands back the lowest FREE id, and nothing reaps a deleted
476	  // server's vzdump archives, so the id freed by a deletion comes back carrying
477	  // the old owner's backups — which every backup surface then attributes to the
478	  // new customer (listBackups/requestRestore key on vmid alone). See
479	  // `pickProvisionVmid` in lib/proxmox.ts. Only for a FRESH allocation: a retry
480	  // keeps the vmid already persisted on the row.
