914	async function reinstall(job: Job) {
915	  const server = await loadServer(job);
916	  if (SANDBOX) {
917	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
918	    await notify(
919	      server.userId,
920	      `Server ${server.hostname} reinstalled (sandbox)`,
921	      "The sandbox server was reinstalled (no real VM was touched).",
922	      `/dashboard/servers/${server.id}`
923	    );
924	    return;
925	  }
926	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
927	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
928	  // EVERY disk the vmid owns, including attached block-storage Volume disks
929	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
930	  // by that vmid, and both purge and the default destroy (which removes disks
931	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
932	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
933	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
934	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
935	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
936	  // can be re-attached after the reinstall. This runs BEFORE any status change or
937	  // destructive call, so a blocked reinstall touches nothing.
938	  //
939	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
940	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
941	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
942	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
943	  // let the worst path through: fill a volume, Detach (the UI says "Data is
944	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
945	  // Detaching is therefore NOT sufficient protection, and telling the customer to
946	  // detach was wrong advice; they must delete the volume (which destroys just
947	  // that disk, deliberately) or move it to another server first.
948	  const pinnedVolumes = await db.volume.findMany({
949	    where: { serverId: server.id },
950	  });
951	  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
952	  const realPinned = pinnedVolumes.filter(
953	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
954	  );
955	  if (realPinned.length > 0) {
956	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
957	    throw new Error(
958	      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
959	        `Reinstalling purges every disk this server owns — including detached volumes ` +
960	        `that are still assigned to it — and that cannot be undone.`
961	    );
962	  }
963	
964	  const { conn } = await nodeFor(server);
965	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
966	  if (server.vmid) await destroyVm(conn, server.vmid);
967	  await provision(job);
968	}
