2420	        console.error("[worker] IP pool sync error", e);
2421	      }
2422	    }
2423	    try {
2424	      const candidate = await db.job.findFirst({
2425	        where: { status: "QUEUED" },
2426	        orderBy: { createdAt: "asc" },
2427	      });
2428	      if (candidate) {
2429	        // Atomic claim: only the worker whose updateMany matches the still-QUEUED
2430	        // row wins. If count===0 another worker (or a retry) already took it, so we
2431	        // skip and re-poll — prevents the same job running twice under concurrency.
2432	        const claim = await db.job.updateMany({
2433	          where: { id: candidate.id, status: "QUEUED" },
2434	          data: { status: "RUNNING", attempts: { increment: 1 } },
2435	        });
2436	        if (claim.count === 1) {
2437	          const claimed = await db.job.findUnique({ where: { id: candidate.id } });
2438	          if (claimed) await runJob(claimed);
2439	        }
2440	        // else: lost the race — loop immediately to grab the next queued job.
2441	      } else {
2442	        await new Promise((r) => setTimeout(r, POLL_MS));
2443	      }
2444	    } catch (e) {
2445	      console.error("[worker] loop error", e);
2446	      await new Promise((r) => setTimeout(r, POLL_MS));
2447	    }
2448	  }
2449	}
